from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

latest_candidate = None
if 'orders_all' in globals() and orders_all:
    sweater_candidates=[]
    for o in orders_all:
        for it in o.get('order_items',[]):
            name=(it.get('product_name') or '')
            if 'sweater' in name.lower():
                sweater_candidates.append({
                    'order_id': o.get('order_id'),
                    'created_at': o.get('created_at'),
                    'product_id': it.get('product_id'),
                    'product_name': name,
                })
    print('sweater_candidates_count', len(sweater_candidates))
    if sweater_candidates:
        latest_candidate = sorted(sweater_candidates, key=lambda x: parse_dt(x['created_at']) or datetime.min, reverse=True)[0]

print('latest_candidate', latest_candidate)

# login token
amazon_token_val = amazon_token if 'amazon_token' in globals() else None
print('amazon_token_present', bool(amazon_token_val))

product_id = latest_candidate['product_id']

res = apis.amazon.write_product_question(product_id=product_id, question=question_text, access_token=amazon_token_val)
